window.docContents[49].resolve({"/Storage-and-commands/Assignment/#Core-C______--Storage-and-commands--Assignment":{"contents":"The left side denotes a location whose type has values, and the right side has a type with values that  accepts at it, . No assignment writes an object, since an object type has no values. The order is the one C++17 fixes for assignment, the right operand before the left one (N4659 §8.18 paragraph 1). The location must be live, , so an assignment through a reference that dangles has no derivation.\n\n","context":"Core C++\u0009Storage and commands","header":"4.3. Assignment","id":"/Storage-and-commands/Assignment/#Core-C______--Storage-and-commands--Assignment"}});